<script setup lang="ts">
import{ref,onMounted}from'vue';import{request}from'../api/client';import StatusBadge from'../components/StatusBadge.vue'
interface History{id:string;operation:string;state:string;message:string;completedSteps:number;createdAt:string;updatedAt:string;items:Array<{source:{path:string};target:string}>}
const items=ref<History[]>([]),page=ref(1),total=ref(0),state=ref(''),busy=ref(false),error=ref('')
async function load(){busy.value=true;error.value='';try{const out=await request<{items:History[];total:number}>(`/media/organize-history?page=${page.value}&pageSize=25&state=${state.value}`);items.value=out.items;total.value=out.total}catch(e){error.value=e instanceof Error?e.message:'历史读取失败'}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="page-heading"><div><h1>媒体整理历史</h1><p>真实文件操作日志：重命名、分类、移动及对账状态。预览不会记作已整理。</p></div><el-button :loading="busy" @click="load">刷新历史</el-button></section><el-alert v-if="error" :title="error" type="error" :closable="false"/><section class="panel"><el-select v-model="state" aria-label="整理状态筛选" @change="page=1;load()"><el-option label="全部状态" value=""/><el-option label="成功" value="succeeded"/><el-option label="需对账" value="needs_reconcile"/><el-option label="失败" value="failed"/><el-option label="执行中" value="running"/></el-select><article v-for="item in items" :key="item.id" class="history-row"><div class="history-head"><strong>{{({organize:'分类整理',rename:'重命名',move:'移动'})[item.operation]??item.operation}}</strong><StatusBadge :state="item.state"/><time>{{new Date(item.createdAt).toLocaleString()}}</time></div><div v-for="(entry,index) in item.items??[]" :key="index" class="history-path"><code>{{entry.source.path}}</code><span>→</span><code>{{entry.target}}</code></div><p class="field-hint">{{item.message||`已确认 ${item.completedSteps} 个步骤`}}</p><RouterLink v-if="item.state==='needs_reconcile'" to="/files" class="inline-link">进入文件管理核对</RouterLink></article><el-empty v-if="!busy&&!items.length" description="暂无实际整理记录"/><el-pagination v-model:current-page="page" :page-size="25" :total="total" layout="prev,pager,next,total" @current-change="load"/></section></template>
<style scoped>.history-row{padding:24px 0;border-bottom:1px solid var(--border)}.history-head{display:flex;flex-wrap:wrap;gap:16px;align-items:center;margin-bottom:16px}.history-head time{color:var(--muted);font-size:12px;margin-left:auto}.history-path{display:grid;grid-template-columns:1fr 24px 1fr;gap:12px;margin:10px 0}.history-path code{line-height:1.7;overflow-wrap:anywhere}.el-pagination{margin-top:24px;overflow:auto}@media(max-width:680px){.history-path{grid-template-columns:1fr}.history-head time{margin-left:0}}</style>
